rule sigma_rule: "Distributed port scan detection" {
    meta:
        description: "Detects distributed port scans from Tor exit nodes"
    condition:
        and (
            process.name == "nmap",
            network.protocol == "tcp",
            network.direction == "inbound"
        )
}

